// CORRECT — escaping at output boundary
$post_title = get_the_title();
echo '<h4>' . esc_html( $post_title ) . '</h4>';

// CORRECT — URL in href attribute
$permalink = get_permalink();
echo '<a href="' . esc_url( $permalink ) . '">' . esc_html( get_the_title() ) . '</a>';

// CORRECT — URL in src attribute
$image_url = get_the_post_thumbnail_url();
echo '<img alt="" src="' . esc_url( $image_url ) . '" />';

// CORRECT — data attribute (JSON/JS context)
$my_value = sanitize_text_field( $_POST['some_value'] ?? '' );
echo '<div data-value="' . esc_attr( $my_value ) . '"></div>';

// CORRECT — For rich HTML that should allow some tags
$content = get_the_content();
echo wp_kses_post( $content );

