// CORRECT — .env is git-ignored and not in repository
// File: .gitignore
.env
.env.local
.env.*.local
/vendor/
/node_modules/

// CORRECT — .env.example exists (template, no real secrets)
// File: .env.example (tracked; used by developers to create .env locally)
DB_HOST=localhost
DB_USER=wp_user
DB_PASSWORD=CHANGE_ME_IN_LOCAL_ENV
API_KEY=your-api-key-here

// CORRECT — Load .env at runtime from gitignored .env file
// File: wp-config.php or config.php
require_once __DIR__ . '/vendor/autoload.php';
$dotenv = Dotenv\Dotenv::createImmutable( __DIR__ );
$dotenv->load();

$db_host = $_ENV['DB_HOST'] ?? 'localhost';
$db_pass = $_ENV['DB_PASSWORD'] ?? '';
$api_key = $_ENV['API_KEY'] ?? '';

// CORRECT — If .env was already committed: remove from history
// $ git rm --cached .env
// $ echo ".env" >> .gitignore
// $ git add .gitignore
// $ git commit -m "Remove tracked .env file with secrets"
// $ git push

entries.bad_pattern:
// WRONG — .env file IS tracked in git (contains real secrets)
// File: .env (committed in git)
DB_HOST=prod.example.com
DB_USER=admin
DB_PASSWORD=SuperSecret123!
API_KEY=sk-live-1234567890abcdef
STRIPE_SECRET=sk_live_...

// WRONG — no .gitignore rule for .env files
// File: .gitignore (missing .env entry)
node_modules/
*.log
// (no .env rule — files get committed)

// WRONG — loading from tracked .env with creds
require_once __DIR__ . '/.env';
$db_pass = $_ENV['DB_PASSWORD'];  // Exposes from history

entries.code_example:
// CORRECT — .gitignore excludes vendor/ but NOT composer.lock
// File: .gitignore
vendor/
node_modules/
.DS_Store
# (no rule for composer.lock — it stays tracked)

// CORRECT — Both files tracked in git
// File: composer.json (tracked)
{
  "name": "my-plugin",
  "require": {
    "vendor/package": "^2.0"
  }
}

// File: composer.lock (tracked — exact versions, reproducible)
{
  "packages": [
    {
      "name": "vendor/package",
      "version": "2.4.3",  // Exact version, not a range
      ...
    }
  ]
}

# Result: deterministic builds
$ composer install
# uses composer.lock; all environments get vendor/package@2.4.3
$ git status
# nothing to commit; lock file is already in git

entries.bad_pattern:
# File: .gitignore (WRONG — excludes the lock file)
vendor/
composer.lock  # <-- WRONG: lock file is gitignored

// File: composer.json (tracked, but lock file missing from git)
{
  "name": "my-plugin",
  "require": {
    "vendor/package": "^2.0"  // Open range; each install gets a different version
  }
}

# Result: random versions installed
$ composer install
$ git status
# composer.lock is NOT in git; every developer's vendor/ may differ

