// CORRECT — read-only public endpoint: __return_true is documented and intentional.
register_rest_route(
    'myplugin/v1',
    '/products',
    [
        'methods'             => WP_REST_Server::READABLE,
        'callback'            => 'myplugin_get_products',
        'permission_callback' => '__return_true', // intentionally public
    ]
);

// CORRECT — mutating endpoint: capability check in permission_callback.
register_rest_route(
    'myplugin/v1',
    '/settings',
    [
        'methods'             => WP_REST_Server::EDITABLE,
        'callback'            => 'myplugin_update_settings',
        'permission_callback' => function () {
            return current_user_can( 'manage_options' );
        },
    ]
);

entries.bad_pattern:
// WRONG — no permission_callback at all (WP 5.5+ emits doing_it_wrong notice;
// access behaviour is the same as __return_true — anyone can call this).
register_rest_route(
    'myplugin/v1',
    '/settings',
    [
        'methods'  => WP_REST_Server::EDITABLE,
        'callback' => 'myplugin_update_settings',
    ]
);

// WRONG — __return_true on a mutating route exposes the operation to any visitor.
register_rest_route(
    'myplugin/v1',
    '/delete-item',
    [
        'methods'             => WP_REST_Server::DELETABLE,
        'callback'            => 'myplugin_delete_item',
        'permission_callback' => '__return_true',
    ]
);

entries.code_example:
// ── Server side: register the AJAX action ───────────────────────────────────
add_action( 'wp_ajax_myplugin_delete_record', 'myplugin_delete_record_handler' );

function myplugin_delete_record_handler(): void {
    // CORRECT — verify nonce before touching anything.
    check_ajax_referer( 'myplugin_delete_nonce', 'security' );

    // CORRECT — capability check after nonce (defence in depth).
    if ( ! current_user_can( 'manage_options' ) ) {
        wp_send_json_error( 'Forbidden', 403 );
    }

    $record_id = absint( $_POST['record_id'] ?? 0 );
    // … perform the deletion …
    wp_send_json_success();
}

// ── Client side: pass the nonce with the request ─────────────────────────────
// In PHP (enqueue + localize):
wp_localize_script(
    'myplugin-admin',
    'MyPlugin',
    [ 'nonce' => wp_create_nonce( 'myplugin_delete_nonce' ) ]
);

entries.bad_pattern:
// WRONG — no nonce check; any authenticated request can trigger this.
add_action( 'wp_ajax_myplugin_delete_record', 'myplugin_delete_record_handler' );

function myplugin_delete_record_handler(): void {
    $record_id = absint( $_POST['record_id'] ?? 0 );
    // Immediately deletes without verifying the request is intentional.
    $wpdb->delete( $wpdb->prefix . 'myplugin_records', [ 'id' => $record_id ] );
    wp_send_json_success();
}

entries.code_example:
// CORRECT — sanitise every superglobal read at the point of retrieval.
$post_id  = absint( $_POST['post_id'] ?? 0 );
$username = sanitize_text_field( wp_unslash( $_POST['username'] ?? '' ) );
$email    = sanitize_email( $_POST['email'] ?? '' );
$url      = sanitize_url( $_POST['redirect_url'] ?? '' );

// CORRECT — integer cast is sufficient for known-numeric fields.
$page = (int) ( $_GET['paged'] ?? 1 );

// CORRECT — wp_unslash() before sanitize_text_field() to strip magic-quote slashes.
$comment = sanitize_textarea_field( wp_unslash( $_POST['comment'] ?? '' ) );

// CORRECT — capability check at the top, before any mutation.
add_action( 'admin_post_myplugin_delete_record', 'myplugin_handle_delete_record' );

function myplugin_handle_delete_record(): void {
    // 1. Verify nonce.
    check_admin_referer( 'myplugin_delete_nonce', 'security' );

    // 2. Verify capability.
    if ( ! current_user_can( 'manage_options' ) ) {
        wp_die( esc_html__( 'You do not have permission to perform this action.', 'myplugin' ) );
    }

    $record_id = absint( $_POST['record_id'] ?? 0 );
    // … delete the record …
    wp_safe_redirect( admin_url( 'admin.php?page=myplugin&deleted=1' ) );
    exit;
}

// CORRECT — post-specific capability using map_meta_cap.
function myplugin_can_edit_post( int $post_id ): bool {
    return current_user_can( 'edit_post', $post_id );
}

entries.bad_pattern:
// WRONG — no capability check; any logged-in user can delete any record.
add_action( 'admin_post_myplugin_delete_record', 'myplugin_handle_delete_record' );

function myplugin_handle_delete_record(): void {
    check_admin_referer( 'myplugin_delete_nonce', 'security' ); // nonce only
    $record_id = absint( $_POST['record_id'] ?? 0 );
    $wpdb->delete( $wpdb->prefix . 'myplugin_records', [ 'id' => $record_id ] );
    wp_safe_redirect( admin_url( 'admin.php?page=myplugin' ) );
    exit;
}

