// CORRECT — ability is visible to MCP clients (Claude Code, Cursor, agents)
wp_register_ability( 'my-plugin/get-data', [
    'label'              => 'Get Data',
    'description'        => 'Retrieve plugin data for agent use',
    'input_schema'       => [ 'type' => 'object' ],
    'execute_callback'   => fn( $input ) => get_option( 'my_plugin_data' ),
    'permission_callback'=> fn() => current_user_can( 'read' ),
    'meta'               => [
        'show_in_rest' => true,          // REST API visibility (unchanged)
        'mcp'          => [
            'public' => true,            // REQUIRED: expose to MCP server
            'type'   => 'tool',          // Optional: 'tool' (default), 'resource', 'prompt'
        ],
        'annotations'  => [
            'readonly'    => true,
            'destructive' => false,
            'idempotent'  => true,
        ],
    ],
] );
// Result: MCP discover-abilities now returns this ability; Claude Code / Cursor can invoke it

entries.bad_pattern:
// WRONG — ability registers but remains invisible to MCP clients
wp_register_ability( 'my-plugin/get-data', [
    'label'              => 'Get Data',
    'description'        => 'Retrieve plugin data for agent use',
    'input_schema'       => [ 'type' => 'object' ],
    'execute_callback'   => fn( $input ) => get_option( 'my_plugin_data' ),
    'permission_callback'=> fn() => current_user_can( 'read' ),
    'meta'               => [
        'show_in_rest' => true,  // Sets REST API visibility — does NOT control MCP
        'annotations'  => [
            'readonly'    => true,
            'destructive' => false,
            'idempotent'  => true,
        ],
    ],
] );
// Result: wp-json REST endpoint works, but MCP discover-abilities returns nothing

entries.code_example:
// CORRECT — import watch from the public @wordpress/interactivity package.
// Requires WordPress 7.0+ (released May 20, 2026).
import { store, watch } from '@wordpress/interactivity';

const { state } = store( 'my-plugin/counter', {
  state: { count: 0 },
} );

// watch() subscribes to every reactive value read inside the callback and
// re-runs the callback whenever any of them change.
watch( () => {
  console.log( 'Count is now', state.count );
} );

entries.bad_pattern:
// WRONG — effect is not exported from @wordpress/interactivity.
// This will throw a module resolution error or import a stale @preact/signals copy.
import { effect } from '@preact/signals';           // direct Preact dep — do not reach inside WP
import { store } from '@wordpress/interactivity';

const { state } = store( 'my-plugin/counter', {
  state: { count: 0 },
} );

// This fires on every signals change but is not the public @wordpress/interactivity API.
effect( () => {
  console.log( 'Count changed to', state.count );
} );

