// CORRECT — restricts to editors and above (minimum for bulk post operations)
wp_register_ability( 'my-plugin/publish-all-drafts', [
    'label'              => 'Publish All Drafts',
    'description'        => 'Publishes every draft post on the site',
    'execute_callback'   => function( $input ) {
        $drafts = get_posts( [ 'post_status' => 'draft', 'numberposts' => -1 ] );
        foreach ( $drafts as $post ) {
            wp_publish_post( $post->ID );
        }
        return [ 'published' => count( $drafts ) ];
    },
    'permission_callback' => function() {
        // 'publish_posts' is the minimum cap for post-publication operations
        return current_user_can( 'publish_posts' );
    },
    'meta' => [
        'annotations' => [
            'destructive' => true,
            'idempotent'  => false,
        ],
        'mcp' => [ 'public' => true, 'type' => 'tool' ],
    ],
] );

entries.bad_pattern:
// WRONG — any logged-in user can execute this mutating ability via MCP
wp_register_ability( 'my-plugin/publish-all-drafts', [
    'label'              => 'Publish All Drafts',
    'description'        => 'Publishes every draft post on the site',
    'execute_callback'   => function( $input ) {
        // mutating: changes post statuses site-wide
        $drafts = get_posts( [ 'post_status' => 'draft', 'numberposts' => -1 ] );
        foreach ( $drafts as $post ) {
            wp_publish_post( $post->ID );
        }
        return [ 'published' => count( $drafts ) ];
    },
    'permission_callback' => '__return_true',  // ← any logged-in user passes
    'meta' => [
        'annotations' => [
            'destructive' => true,   // developer correctly declared mutation...
            'idempotent'  => false,  // ...but permission_callback contradicts it
        ],
        'mcp' => [ 'public' => true, 'type' => 'tool' ],
    ],
] );

entries.code_example:
// CORRECT — do not read state.navigation.hasStarted or hasFinished.
// An official navigation-state tracking mechanism is planned for WP 7.1.
// Until then, manage loading state locally in your own store.
import { store } from '@wordpress/interactivity';

const { state, actions } = store( 'my-plugin/nav-loader', {
  state: { loading: false },
  actions: {
    async navigate( url: string ) {
      state.loading = true;
      try {
        await actions.navigate( url ); // core/router navigate action
      } finally {
        state.loading = false;
      }
    },
  },
} );

entries.bad_pattern:
// WRONG — deprecated since WP 7.0, will break in WP 7.1.
// Accessing hasStarted or hasFinished triggers a console warning in WP 7.0 dev mode (SCRIPT_DEBUG).
import { store } from '@wordpress/interactivity';

const { state } = store( 'core/router', {} );

function showLoader() {
  if ( state.navigation.hasStarted && ! state.navigation.hasFinished ) {
    document.getElementById( 'loader' ).style.display = 'block';
  } else {
    document.getElementById( 'loader' ).style.display = 'none';
  }
}

entries.code_example:
// CORRECT — all fields declared, type + required enforced by the Abilities API
wp_register_ability( 'my-plugin/delete-post', [
    'label'              => 'Delete Post',
    'description'        => 'Deletes a post by ID',
    'input_schema'       => [
        'type'       => 'object',
        'properties' => [
            'post_id' => [
                'type'        => 'integer',
                'description' => 'The ID of the post to delete',
                'minimum'     => 1,
            ],
        ],
        'required'             => [ 'post_id' ],
        'additionalProperties' => false,  // reject unknown fields
    ],
    'execute_callback'   => function( $input ) {
        // $input['post_id'] is guaranteed to be a positive integer by the schema
        return wp_delete_post( $input['post_id'], true ) !== false;
    },
    'permission_callback' => function() { return current_user_can( 'delete_posts' ); },
    'meta' => [ 'mcp' => [ 'public' => true, 'type' => 'tool' ] ],
] );

entries.bad_pattern:
// WRONG — empty input_schema: execute_callback receives unvalidated input
wp_register_ability( 'my-plugin/delete-post', [
    'label'              => 'Delete Post',
    'description'        => 'Deletes a post by ID',
    'input_schema'       => [ 'type' => 'object' ],  // ← no 'properties' declared
    'execute_callback'   => function( $input ) {
        // $input['post_id'] is unvalidated — could be a non-integer, a negative,
        // or absent. wp_delete_post() with a bad ID silently fails or deletes wp_post 0.
        return wp_delete_post( $input['post_id'], true );
