// CORRECT — use wp_get_loading_optimization_attributes() since WP 6.3.0.
// Returns an array of attribute key-value pairs, not a single loading value.
add_filter( 'wp_get_attachment_image_attributes', function( $attr, $attachment, $size ) {
    // wp_get_loading_optimization_attributes() returns array e.g. ['loading' => 'lazy', 'decoding' => 'async']
    $opt_attrs = wp_get_loading_optimization_attributes(
        'img',
        array(
            'context'        => 'the_content',
            'width'          => isset( $attr['width'] ) ? (int) $attr['width'] : 0,
            'height'         => isset( $attr['height'] ) ? (int) $attr['height'] : 0,
        ),
        get_the_ID() ?: 0
    );
    // Merge optimization attributes into existing attrs (do not override manually set ones).
    foreach ( $opt_attrs as $key => $value ) {
        if ( ! isset( $attr[ $key ] ) ) {
            $attr[ $key ] = $value;
        }
    }
    return $attr;
}, 10, 3 );

