entries.bad_pattern:
# Anti-pattern: ZIP uploads and manual vendor management
# 1. Downloading a plugin as ZIP and uploading via wp-admin — no version tracking
# 2. Committing the vendor/ directory to Git — bloats the repo, conflicts on update
# 3. require_once scattering:
require_once get_template_directory() . '/inc/helpers.php';
require_once get_template_directory() . '/inc/cpts.php';
require_once get_template_directory() . '/inc/api.php';
# Replace all of these with a single composer dump-autoload

// Anti-pattern: security rules in a regular plugin
// wp-content/plugins/my-security-plugin/my-security-plugin.php
// client can deactivate it from wp-admin Plugins screen
// one click removes REST restrictions, XML-RPC protection, logging

// Also wrong: one massive mu-plugins/everything.php with 1000+ lines
// unmaintainable, unclear load order, impossible to test in isolation

// Anti-pattern 1: expecting WordPress to auto-load a file in a subdirectory
// wp-content/mu-plugins/project-core/security.php
// WordPress NEVER loads this automatically; you need a top-level loader file

// Anti-pattern 2: no loader, relying on a normal plugin to include core modules
// wp-content/plugins/project-setup/project-setup.php
// add_action('plugins_loaded', function() { require_once '...'; });
// normal plugins can be deactivated; core modules must not depend on activation

