require_once __DIR__ . '/vendor/autoload.php';

add_action('init', [new \MyPlugin\PostTypes\ProductPostType(), 'register']);

# Install release-it as a dev dependency
npm install --save-dev release-it

# Minimal .release-it.json config
{
  "git": {
    "commitMessage": "chore: release v${version}",
    "tagName": "v${version}"
  },
  "github": {
    "release": true,
    "releaseName": "v${version}"
  },
  "npm": {
    "publish": false
  },
  "hooks": {
    "before:init": ["npm run build"],
    "after:bump": "npm run build"
  }
}

# Run a release interactively
npx release-it

# Run a specific bump non-interactively (in CI)
npx release-it patch --no-git.requireCleanWorkingDir --ci

entries.bad_pattern:
// Anti-pattern: no environment differentiation
// wp-config.php on every environment, identical config
define('WP_DEBUG', true);         // debug on in production
define('SAVEQUERIES', true);      // performance hit in production
// MAIL_DRIVER never set — assumes smtp on every environment
// WP_ENVIRONMENT_TYPE never defined — wp_get_environment_type() returns 'production' by default
//   but the codebase has no gate logic relying on it, so the default is meaningless

// Anti-patterns the book documents:

// 1. Hardcoded credentials in wp-config.php committed to Git
define('DB_PASSWORD', 'myproductionpassword123');

// 2. Secrets as comments in workflow YAML
# deploy_key: abc123secretkey   ← exposed in repo history

// 3. One key for all environments
// Same APP_SECRET on local, staging, and production
// Compromise of staging = compromise of production

// 4. "Dummy values, swap them later" — they never get swapped

// 5. .env committed with a message like:
// "add env for staging (temp!)"
// three commits later, nobody deleted it

