// tests/e2e/admin-login.spec.js
// Example: tests the WP admin login flow end-to-end.

import { test, expect } from '@playwright/test';

test('admin can log in and reach the dashboard', async ({ page }) => {
  await page.goto('/wp-login.php');

  await page.fill('#user_login', 'admin');
  await page.fill('#user_pass', 'password');
  await page.click('#wp-submit');

  await expect(page).toHaveURL(/wp-admin/);
  await expect(page.locator('#wpadminbar')).toBeVisible();
});

test('contact form is visible and submittable', async ({ page }) => {
  await page.goto('/contact');

  const form = page.locator('form.contact-form');
  await expect(form).toBeVisible();

  await form.locator('input[name="name"]').fill('Test User');
  await form.locator('input[name="email"]').fill('test@example.com');
  await form.locator('textarea[name="message"]').fill('Test message');
  await form.locator('button[type="submit"]').click();

  await expect(page.locator('.form-success')).toBeVisible();
});

// tests/visual/homepage.spec.js
// Visual regression: homepage on desktop and mobile.

import { test, expect } from '@playwright/test';

test('homepage matches reference on desktop', async ({ page }) => {
  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto('/');
  // Mask dynamic elements before diffing.
  await page.locator('.rotating-banner').evaluate((el) => (el.style.visibility = 'hidden'));
  await expect(page).toHaveScreenshot('homepage-desktop.png', { threshold: 0.1 });
});

test('homepage matches reference on mobile', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 812 });
  await page.goto('/');
  await expect(page).toHaveScreenshot('homepage-mobile.png', { threshold: 0.1 });
});

test('contact form is visually correct when filled', async ({ page }) => {
  await page.goto('/contact');
  await page.fill('input[name="name"]', 'Jane Doe');
  await page.fill('input[name="email"]', 'jane@example.com');
  await expect(page).toHaveScreenshot('contact-filled.png', { threshold: 0.1 });
});

